// Layout thrashing and the fix: batch reads, then batch writes.

// BAD: each iteration writes then reads, forcing a synchronous layout N times.
export function equaliseHeightsSlow(cards: HTMLElement[]): void {
  for (const card of cards) {
    card.style.height = 'auto'; // write (invalidates layout)
    const h = card.offsetHeight; // read (forces layout now)
    card.style.height = `${Math.ceil(h / 8) * 8}px`; // write again
  }
}

// GOOD: one write phase, one read phase, one write phase -> at most two layouts.
export function equaliseHeightsFast(cards: HTMLElement[]): void {
  for (const card of cards) card.style.height = 'auto';
  const heights = cards.map((card) => card.offsetHeight); // single forced layout
  requestAnimationFrame(() => {
    cards.forEach((card, i) => {
      card.style.height = `${Math.ceil(heights[i] / 8) * 8}px`;
    });
  });
}

// Prefer observers to polling geometry in scroll or resize handlers.
export function watchSize(el: Element, onSize: (w: number, h: number) => void): () => void {
  const ro = new ResizeObserver(([entry]) => {
    const { inlineSize, blockSize } = entry.contentBoxSize[0];
    onSize(inlineSize, blockSize);
  });
  ro.observe(el);
  return () => ro.disconnect();
}

// Breaking a long task into chunks so input can be handled between them.

type Yielder = () => Promise<void>;

// scheduler.yield() resumes at the front of the queue (Chromium); fall back to a macrotask elsewhere.
const yieldToMain: Yielder = () => {
  const s = (globalThis as { scheduler?: { yield?: () => Promise<void> } }).scheduler;
  if (s?.yield) return s.yield();
  return new Promise((resolve) => setTimeout(resolve, 0));
};

export async function processInChunks<T>(
  items: readonly T[],
  work: (item: T) => void,
  budgetMs = 8,
): Promise<void> {
  let deadline = performance.now() + budgetMs;
  for (const item of items) {
    work(item);
    if (performance.now() >= deadline) {
      await yieldToMain(); // lets the browser handle input and render a frame
      deadline = performance.now() + budgetMs;
    }
  }
}

// Leak-free listeners: one AbortController tears everything down.
export function attachGlobalShortcuts(onSave: () => void): () => void {
  const ac = new AbortController();
  window.addEventListener(
    'keydown',
    (e) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 's') {
        e.preventDefault();
        onSave();
      }
    },
    { signal: ac.signal },
  );
  window.addEventListener('wheel', () => {}, { passive: true, signal: ac.signal });
  return () => ac.abort();
}

// app/product/[id]/page.tsx (Next.js App Router, Cache Components enabled)
import { Suspense } from 'react';
import { cacheLife, cacheTag } from 'next/cache';
import { AddToCart } from './add-to-cart'; // 'use client' component
import { db } from '@/lib/db';

async function getProduct(id: string) {
  'use cache';
  cacheTag(`product-${id}`); // invalidated by the pricing service
  cacheLife('hours');
  return db.product.findUnique({ where: { id } });
}

async function Reviews({ id }: { id: string }) {
  const reviews = await db.review.findMany({ where: { productId: id }, take: 10 });
  return (
    <ul>
      {reviews.map((r) => (
        <li key={r.id}>{r.text}</li>
      ))}
    </ul>
  );
}

export default async function ProductPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const product = await getProduct(id);
  if (!product) return <p>Not found</p>;

  return (
    <main>
      <h1>{product.name}</h1>
      <p>{product.description}</p>
      {/* Only this subtree ships JS and hydrates */}
      <AddToCart sku={product.sku} price={product.price} />
      {/* Slow data streams in without delaying the shell */}
      <Suspense fallback={<div className="h-64" aria-busy="true" />}>
        <Reviews id={id} />
      </Suspense>
    </main>
  );
}

