// app/api/price-webhook/route.ts — on-demand invalidation from the pricing service
import { revalidateTag } from 'next/cache';
import { z } from 'zod';

const body = z.object({ productId: z.string().min(1), secret: z.string() });

export async function POST(req: Request): Promise<Response> {
  const parsed = body.safeParse(await req.json());
  if (!parsed.success || parsed.data.secret !== process.env.PRICE_WEBHOOK_SECRET) {
    return new Response('unauthorised', { status: 401 });
  }
  // 'max' = serve stale while the next visit regenerates in the background
  revalidateTag(`product-${parsed.data.productId}`, 'max');
  return Response.json({ ok: true });
}

// A framework-free view of the CDN headers each kind of response should carry.
export const cacheHeaders = {
  hashedAsset: 'public, max-age=31536000, immutable',
  sharedHtml: 'public, s-maxage=60, stale-while-revalidate=600',
  personalHtml: 'private, no-cache',
  sensitive: 'no-store',
} as const;

// rum.ts — field Core Web Vitals with attribution, sent with sendBeacon
import { onCLS, onINP, onLCP, type CLSMetricWithAttribution, type INPMetricWithAttribution, type LCPMetricWithAttribution } from 'web-vitals/attribution';

type Beacon = {
  name: 'LCP' | 'INP' | 'CLS';
  value: number;
  rating: 'good' | 'needs-improvement' | 'poor';
  page: string; // route template, not the raw URL (avoid personal data in paths)
  detail: Record<string, string | number | undefined>;
};

const template = () => document.body.dataset.template ?? 'unknown';

function send(b: Beacon): void {
  const body = JSON.stringify(b);
  if (!navigator.sendBeacon('/rum', body)) {
    void fetch('/rum', { method: 'POST', body, keepalive: true });
  }
}

export function startRum(): void {
  onLCP((m: LCPMetricWithAttribution) => {
    const a = m.attribution;
    send({
      name: 'LCP', value: m.value, rating: m.rating, page: template(),
      detail: {
        ttfb: a.timeToFirstByte,
        loadDelay: a.resourceLoadDelay,
        loadDuration: a.resourceLoadDuration,
        renderDelay: a.elementRenderDelay,
      },
    });
  });

  onINP((m: INPMetricWithAttribution) => {
    const a = m.attribution;
    send({
      name: 'INP', value: m.value, rating: m.rating, page: template(),
      detail: {
        target: a.interactionTarget, // a CSS selector for the element
        type: a.interactionType,
        inputDelay: a.inputDelay,
        processing: a.processingDuration,
        presentation: a.presentationDelay,
      },
    });
  });

  onCLS((m: CLSMetricWithAttribution) => {
    send({
      name: 'CLS', value: m.value, rating: m.rating, page: template(),
      detail: { source: m.attribution.largestShiftTarget, largest: m.attribution.largestShiftValue },
    });
  });
}

// Keeping a filter interaction under 200 ms: urgent update first, heavy update as a transition.
'use client';
import { lazy, Suspense, useMemo, useState, useTransition } from 'react';

type Product = { id: string; name: string; tags: string[] };

const SizeGuideChart = lazy(() => import('./size-guide-chart')); // only loaded when opened

export function ProductFilter({ products }: { products: Product[] }) {
  const [tag, setTag] = useState<string | null>(null); // urgent: the chip highlight
  const [listTag, setListTag] = useState<string | null>(null); // non-urgent: the big list
  const [isPending, startTransition] = useTransition();
  const [showGuide, setShowGuide] = useState(false);

  // Precompute an index once instead of scanning every product on every click.
  const byTag = useMemo(() => {
    const index = new Map<string, Product[]>();
    for (const p of products) for (const t of p.tags) index.set(t, [...(index.get(t) ?? []), p]);
    return index;
  }, [products]);

  const visible = listTag ? byTag.get(listTag) ?? [] : products;

  function choose(next: string) {
    setTag(next); // paints immediately
    startTransition(() => setListTag(next)); // interruptible re-render
  }

  return (
    <section>
      {[...byTag.keys()].map((t) => (
        <button key={t} aria-pressed={tag === t} onClick={() => choose(t)}>
          {t}
        </button>
      ))}
      <p aria-live="polite">{isPending ? 'Updating…' : `${visible.length} products`}</p>
      {/* In a real list of thousands, render through a virtualiser such as @tanstack/react-virtual */}
      <ul style={{ opacity: isPending ? 0.6 : 1 }}>
        {visible.slice(0, 50).map((p) => (
          <li key={p.id}>{p.name}</li>
        ))}
      </ul>
      <button onClick={() => setShowGuide(true)}>Size guide</button>
      {showGuide && (
        <Suspense fallback={<p>Loading size guide…</p>}>
          <SizeGuideChart />
        </Suspense>
      )}
    </section>
  );
}

